        try:
            res = subprocess.run(["./executable", "-d", ".", "-f", "temp", "AB"], capture_output=True, text=True, timeout=1).stdout.replace("\n", "")
            print(f"{c1} + {c2} -> {res}")
        except Exception as e:
            print(f"FAILED on {c1} + {c2}: {e}")
