import subprocess

chars = "_|/\\[]{}()<>"
for c1 in chars:
    for c2 in chars:
        font = "flf2a$ 2 2 2 15 1 0 24463 0\nComment\n"
        for i in range(32, 127):
            if i == ord('A'):
                font += f"A{c1}@\nA{c1}@@\n"
            elif i == ord('B'):
                font += f"{c2}B@\n{c2}B@@\n"
            else:
                font += "  @\n  @@\n"
        with open("temp.flf", "w") as f:
            f.write(font)

        try:
            res = subprocess.run(["./executable", "-s", "-d", ".", "-f", "temp", "AB"], capture_output=True, text=True, timeout=1).stdout
            # res is something like 'A|B\nA|B\n'. We just need the first line's middle char.
            line = res.split('\n')[0]
            if len(line) == 3:
                smushed = line[1]
                print(f"{c1} + {c2} -> {smushed}")
            else:
                print(f"{c1} + {c2} -> NO SMUSH (len={len(line)}, {line})")
        except Exception as e:
            pass
EOF
python3 test_smush_all.py > smush_matrix.txt
