        return strip_min_lead(char_lines)

    max_overlap_for_rows = []
    for r in range(height):
        res_row = res_lines[r]
        ch_row = char_lines[r]

        r_pad = len(res_row) - len(res_row.rstrip(' '))
        if r_pad == len(res_row): r_pad = len(res_row)

        l_pad = len(ch_row) - len(ch_row.lstrip(' '))
        if l_pad == len(ch_row): l_pad = len(ch_row)

        max_overlap_for_rows.append(r_pad + l_pad)

    kerning_ov = min(max_overlap_for_rows) if max_overlap_for_rows else 0
    overlap = kerning_ov

    if mode_val == 'smushing':
        can_smush = True
        for r in range(height):
            if max_overlap_for_rows[r] == kerning_ov:
                r_pad = len(res_lines[r]) - len(res_lines[r].rstrip(' '))
                l_pad = len(char_lines[r]) - len(char_lines[r].lstrip(' '))

                idx_left = len(res_lines[r]) - 1 - r_pad
                idx_right = l_pad

                if idx_left < 0 or idx_right >= len(char_lines[r]):
                    can_smush = False
                    break

                a = res_lines[r][idx_left]
                b = char_lines[r][idx_right]

                sm = smush_chars(a, b, lay_val, hb)
                if sm is None:
                    can_smush = False
                    break
        if can_smush:
            overlap = kerning_ov + 1
    elif mode_val == 'full_width':
        overlap = 0

    new_res = []
    for r in range(height):
        res_row = res_lines[r]
        ch_row = char_lines[r]

        merged = ""
        for k in range(overlap):
            a = res_row[-overlap + k] if overlap > 0 else ''
            b = ch_row[k] if overlap > 0 else ''
            if a == ' ': merged += b
            elif b == ' ': merged += a
            else:
                sm = smush_chars(a, b, lay_val, hb)
                merged += sm if sm else a

        if overlap > 0:
            new_res.append(res_row[:-overlap] + merged + ch_row[overlap:])
        else:
            new_res.append(res_row + ch_row)
    return new_res

def print_rendered(res_lines):
