    for r in range(height):
        line = res_lines[r].replace(hardblank, ' ')
        pad = 0
        if align == 'center':
            pad = max(0, (width_limit - len(line)) // 2)
        elif align == 'right':
            pad = max(0, width_limit - len(line))
        print(' ' * pad + line)

lines_of_msg = msg.split('\n')
for line_msg in lines_of_msg:
    tokens = re.findall(r'\S+|\s+', line_msg)

    current_line_chars = []
    current_rendered = [''] * height
    pending_spaces = []

    for token in tokens:
        if re.match(r'\s+', token):
            if not current_line_chars:
                for c in token:
                    if ord(c) in chars:
                        new_r = try_add(current_rendered, chars[ord(c)], current_mode, layout, hardblank)
                        if len(new_r[0]) <= width_limit or not current_rendered[0]:
                            current_rendered = new_r
                            current_line_chars.append(c)
            else:
                pending_spaces.extend(list(token))
        else:
