            # test adding pending_spaces + word
            test_rendered = current_rendered[:]
            test_chars = current_line_chars[:]

            fits = True
            for c in pending_spaces + word_chars:
                if ord(c) not in chars: continue
                new_r = try_add(test_rendered, chars[ord(c)], current_mode, layout, hardblank)
                if len(new_r[0]) > width_limit and test_rendered[0]:
                    fits = False
                    break
                test_rendered = new_r
                test_chars.append(c)

            if fits:
                current_rendered = test_rendered
                current_line_chars = test_chars
                pending_spaces = []
            else:
                if current_line_chars:
                    print_rendered(current_rendered)
                    current_line_chars = []
                    current_rendered = [''] * height

                pending_spaces = []
                # try to fit word
                test_rendered = current_rendered[:]
                test_chars = current_line_chars[:]
                w_fits = True
                for c in word_chars:
                    if ord(c) not in chars: continue
                    new_r = try_add(test_rendered, chars[ord(c)], current_mode, layout, hardblank)
                    if len(new_r[0]) > width_limit and test_rendered[0]:
                        w_fits = False
                        break
                    test_rendered = new_r
                    test_chars.append(c)

                if w_fits:
                    current_rendered = test_rendered
                    current_line_chars = test_chars
                else:
                    # char wrap
                    for c in word_chars:
                        if ord(c) not in chars: continue
                        new_r = try_add(current_rendered, chars[ord(c)], current_mode, layout, hardblank)
                        if len(new_r[0]) <= width_limit or not current_rendered[0]:
                            current_rendered = new_r
                            current_line_chars.append(c)
                        else:
                            print_rendered(current_rendered)
                            current_rendered = try_add([''] * height, chars[ord(c)], current_mode, layout, hardblank)
                            current_line_chars = [c]

    if current_line_chars:
        print_rendered(current_rendered)

